private int f(int i, int prev, int n, int k, int x) {
    if (i == n) return prev == x ? 1 : 0;
    long ways = 0;
    for (int v = 1; v <= k; v++) {
        if (v != prev) ways += f(i + 1, v, n, k, x);
    }
    return (int) (ways % 1_000_000_007L);
}

