public int countArray(int n, int k, int x) {
    final long MOD = 1_000_000_007L;
    long same = (x == 1) ? 1 : 0;
    long diff = (x == 1) ? 0 : 1;
    for (int i = 2; i <= n; i++) {
        long newSame = diff % MOD;
        long newDiff = (same * (k - 1) % MOD + diff * (k - 2) % MOD) % MOD;
        same = newSame;
        diff = newDiff;
    }
    return (int) (same % MOD);
}

public int countArray(int n, int k, int x) {
    final long MOD = 1_000_000_007L;
    long base = power(k - 1, n - 1, MOD);
    long sign = ((n - 1) % 2 == 0) ? 1 : MOD - 1; // +1 or -1 mod p
    long numerator;
    if (x == 1) {
        numerator = (base + (long) (k - 1) % MOD * sign) % MOD;
    } else {
        numerator = (base - sign % MOD + MOD) % MOD;
    }
    long invK = power(k, MOD - 2, MOD); // Fermat inverse
    return (int) (numerator * invK % MOD);
}

private long power(long b, long e, long mod) {
    b %= mod;
    long r = 1;
    while (e > 0) {
        if ((e & 1) == 1) r = r * b % mod;
        b = b * b % mod;
        e >>= 1;
    }
    return r;
}

