def count_array(self, n: int, k: int, x: int) -> int:
    MOD = 1_000_000_007
    base = pow(k - 1, n - 1, MOD)
    sign = 1 if (n - 1) % 2 == 0 else -1
    if x == 1:
        numerator = (base + (k - 1) * sign) % MOD
    else:
        numerator = (base - sign) % MOD
    inv_k = pow(k, MOD - 2, MOD)  # Fermat's little theorem
    return (numerator * inv_k) % MOD

